-- Mandarin: the HSK 1 to 6 vocabulary (HSK 2.0 list, 4993 words, from
-- github.com/clem109/hsk-vocabulary, MIT), in 200 levels of about 25 words
-- (hsk1-1 to hsk6-100, after hsk-1 and hsk-2), with pinyin and French and
-- English meanings. Replayable: upserts the levels and replaces their words.
-- Mandarin : hsk1-1, hsk1-2, hsk1-3, hsk1-4, hsk1-5, hsk1-6, hsk2-1, hsk2-2, hsk2-3, hsk2-4.
-- Rejouable : met ces niveaux à jour et remplace leurs mots.
INSERT INTO langues.levels (language_code, slug, framework, position, title, description)
SELECT 'zh', n.slug, 'HSK', n.position, n.title, n.description
  FROM jsonb_to_recordset($zh$[{"slug": "hsk1-1", "position": 3, "title": {"fr": "HSK 1 · 1", "en": "HSK 1 · 1"}, "description": {"fr": "Vocabulaire du HSK 1, partie 1 sur 6.", "en": "HSK 1 vocabulary, part 1 of 6."}}, {"slug": "hsk1-2", "position": 4, "title": {"fr": "HSK 1 · 2", "en": "HSK 1 · 2"}, "description": {"fr": "Vocabulaire du HSK 1, partie 2 sur 6.", "en": "HSK 1 vocabulary, part 2 of 6."}}, {"slug": "hsk1-3", "position": 5, "title": {"fr": "HSK 1 · 3", "en": "HSK 1 · 3"}, "description": {"fr": "Vocabulaire du HSK 1, partie 3 sur 6.", "en": "HSK 1 vocabulary, part 3 of 6."}}, {"slug": "hsk1-4", "position": 6, "title": {"fr": "HSK 1 · 4", "en": "HSK 1 · 4"}, "description": {"fr": "Vocabulaire du HSK 1, partie 4 sur 6.", "en": "HSK 1 vocabulary, part 4 of 6."}}, {"slug": "hsk1-5", "position": 7, "title": {"fr": "HSK 1 · 5", "en": "HSK 1 · 5"}, "description": {"fr": "Vocabulaire du HSK 1, partie 5 sur 6.", "en": "HSK 1 vocabulary, part 5 of 6."}}, {"slug": "hsk1-6", "position": 8, "title": {"fr": "HSK 1 · 6", "en": "HSK 1 · 6"}, "description": {"fr": "Vocabulaire du HSK 1, partie 6 sur 6.", "en": "HSK 1 vocabulary, part 6 of 6."}}, {"slug": "hsk2-1", "position": 9, "title": {"fr": "HSK 2 · 1", "en": "HSK 2 · 1"}, "description": {"fr": "Vocabulaire du HSK 2, partie 1 sur 6.", "en": "HSK 2 vocabulary, part 1 of 6."}}, {"slug": "hsk2-2", "position": 10, "title": {"fr": "HSK 2 · 2", "en": "HSK 2 · 2"}, "description": {"fr": "Vocabulaire du HSK 2, partie 2 sur 6.", "en": "HSK 2 vocabulary, part 2 of 6."}}, {"slug": "hsk2-3", "position": 11, "title": {"fr": "HSK 2 · 3", "en": "HSK 2 · 3"}, "description": {"fr": "Vocabulaire du HSK 2, partie 3 sur 6.", "en": "HSK 2 vocabulary, part 3 of 6."}}, {"slug": "hsk2-4", "position": 12, "title": {"fr": "HSK 2 · 4", "en": "HSK 2 · 4"}, "description": {"fr": "Vocabulaire du HSK 2, partie 4 sur 6.", "en": "HSK 2 vocabulary, part 4 of 6."}}]$zh$)
       AS n(slug text, position smallint, title jsonb, description jsonb)
ON CONFLICT (language_code, slug) DO UPDATE
   SET framework = excluded.framework, position = excluded.position,
       title = excluded.title, description = excluded.description;
DELETE FROM langues.words w USING langues.levels l
 WHERE w.level_id = l.id AND l.language_code = 'zh'
   AND l.slug IN ('hsk1-1', 'hsk1-2', 'hsk1-3', 'hsk1-4', 'hsk1-5', 'hsk1-6', 'hsk2-1', 'hsk2-2', 'hsk2-3', 'hsk2-4');
