  FROM jsonb_to_recordset($zh$[{"slug": "hsk3-9", "position": 23, "title": {"fr": "HSK 3 · 9", "en": "HSK 3 · 9"}, "description": {"fr": "Vocabulaire du HSK 3, partie 9 sur 12.", "en": "HSK 3 vocabulary, part 9 of 12."}}, {"slug": "hsk3-10", "position": 24, "title": {"fr": "HSK 3 · 10", "en": "HSK 3 · 10"}, "description": {"fr": "Vocabulaire du HSK 3, partie 10 sur 12.", "en": "HSK 3 vocabulary, part 10 of 12."}}, {"slug": "hsk3-11", "position": 25, "title": {"fr": "HSK 3 · 11", "en": "HSK 3 · 11"}, "description": {"fr": "Vocabulaire du HSK 3, partie 11 sur 12.", "en": "HSK 3 vocabulary, part 11 of 12."}}, {"slug": "hsk3-12", "position": 26, "title": {"fr": "HSK 3 · 12", "en": "HSK 3 · 12"}, "description": {"fr": "Vocabulaire du HSK 3, partie 12 sur 12.", "en": "HSK 3 vocabulary, part 12 of 12."}}, {"slug": "hsk4-1", "position": 27, "title": {"fr": "HSK 4 · 1", "en": "HSK 4 · 1"}, "description": {"fr": "Vocabulaire du HSK 4, partie 1 sur 24.", "en": "HSK 4 vocabulary, part 1 of 24."}}, {"slug": "hsk4-2", "position": 28, "title": {"fr": "HSK 4 · 2", "en": "HSK 4 · 2"}, "description": {"fr": "Vocabulaire du HSK 4, partie 2 sur 24.", "en": "HSK 4 vocabulary, part 2 of 24."}}, {"slug": "hsk4-3", "position": 29, "title": {"fr": "HSK 4 · 3", "en": "HSK 4 · 3"}, "description": {"fr": "Vocabulaire du HSK 4, partie 3 sur 24.", "en": "HSK 4 vocabulary, part 3 of 24."}}, {"slug": "hsk4-4", "position": 30, "title": {"fr": "HSK 4 · 4", "en": "HSK 4 · 4"}, "description": {"fr": "Vocabulaire du HSK 4, partie 4 sur 24.", "en": "HSK 4 vocabulary, part 4 of 24."}}, {"slug": "hsk4-5", "position": 31, "title": {"fr": "HSK 4 · 5", "en": "HSK 4 · 5"}, "description": {"fr": "Vocabulaire du HSK 4, partie 5 sur 24.", "en": "HSK 4 vocabulary, part 5 of 24."}}, {"slug": "hsk4-6", "position": 32, "title": {"fr": "HSK 4 · 6", "en": "HSK 4 · 6"}, "description": {"fr": "Vocabulaire du HSK 4, partie 6 sur 24.", "en": "HSK 4 vocabulary, part 6 of 24."}}]$zh$)
