  FROM jsonb_to_recordset($zh$[{"slug": "hsk4-7", "position": 33, "title": {"fr": "HSK 4 · 7", "en": "HSK 4 · 7"}, "description": {"fr": "Vocabulaire du HSK 4, partie 7 sur 24.", "en": "HSK 4 vocabulary, part 7 of 24."}}, {"slug": "hsk4-8", "position": 34, "title": {"fr": "HSK 4 · 8", "en": "HSK 4 · 8"}, "description": {"fr": "Vocabulaire du HSK 4, partie 8 sur 24.", "en": "HSK 4 vocabulary, part 8 of 24."}}, {"slug": "hsk4-9", "position": 35, "title": {"fr": "HSK 4 · 9", "en": "HSK 4 · 9"}, "description": {"fr": "Vocabulaire du HSK 4, partie 9 sur 24.", "en": "HSK 4 vocabulary, part 9 of 24."}}, {"slug": "hsk4-10", "position": 36, "title": {"fr": "HSK 4 · 10", "en": "HSK 4 · 10"}, "description": {"fr": "Vocabulaire du HSK 4, partie 10 sur 24.", "en": "HSK 4 vocabulary, part 10 of 24."}}, {"slug": "hsk4-11", "position": 37, "title": {"fr": "HSK 4 · 11", "en": "HSK 4 · 11"}, "description": {"fr": "Vocabulaire du HSK 4, partie 11 sur 24.", "en": "HSK 4 vocabulary, part 11 of 24."}}, {"slug": "hsk4-12", "position": 38, "title": {"fr": "HSK 4 · 12", "en": "HSK 4 · 12"}, "description": {"fr": "Vocabulaire du HSK 4, partie 12 sur 24.", "en": "HSK 4 vocabulary, part 12 of 24."}}, {"slug": "hsk4-13", "position": 39, "title": {"fr": "HSK 4 · 13", "en": "HSK 4 · 13"}, "description": {"fr": "Vocabulaire du HSK 4, partie 13 sur 24.", "en": "HSK 4 vocabulary, part 13 of 24."}}, {"slug": "hsk4-14", "position": 40, "title": {"fr": "HSK 4 · 14", "en": "HSK 4 · 14"}, "description": {"fr": "Vocabulaire du HSK 4, partie 14 sur 24.", "en": "HSK 4 vocabulary, part 14 of 24."}}, {"slug": "hsk4-15", "position": 41, "title": {"fr": "HSK 4 · 15", "en": "HSK 4 · 15"}, "description": {"fr": "Vocabulaire du HSK 4, partie 15 sur 24.", "en": "HSK 4 vocabulary, part 15 of 24."}}, {"slug": "hsk4-16", "position": 42, "title": {"fr": "HSK 4 · 16", "en": "HSK 4 · 16"}, "description": {"fr": "Vocabulaire du HSK 4, partie 16 sur 24.", "en": "HSK 4 vocabulary, part 16 of 24."}}]$zh$)
       AS n(slug text, position smallint, title jsonb, description jsonb)
ON CONFLICT (language_code, slug) DO UPDATE
   SET framework = excluded.framework, position = excluded.position,
       title = excluded.title, description = excluded.description;
DELETE FROM langues.words w USING langues.levels l
 WHERE w.level_id = l.id AND l.language_code = 'zh'
   AND l.slug IN ('hsk4-7', 'hsk4-8', 'hsk4-9', 'hsk4-10', 'hsk4-11', 'hsk4-12', 'hsk4-13', 'hsk4-14', 'hsk4-15', 'hsk4-16');
