  FROM jsonb_to_recordset($zh$[{"slug": "hsk5-33", "position": 83, "title": {"fr": "HSK 5 · 33", "en": "HSK 5 · 33"}, "description": {"fr": "Vocabulaire du HSK 5, partie 33 sur 52.", "en": "HSK 5 vocabulary, part 33 of 52."}}, {"slug": "hsk5-34", "position": 84, "title": {"fr": "HSK 5 · 34", "en": "HSK 5 · 34"}, "description": {"fr": "Vocabulaire du HSK 5, partie 34 sur 52.", "en": "HSK 5 vocabulary, part 34 of 52."}}, {"slug": "hsk5-35", "position": 85, "title": {"fr": "HSK 5 · 35", "en": "HSK 5 · 35"}, "description": {"fr": "Vocabulaire du HSK 5, partie 35 sur 52.", "en": "HSK 5 vocabulary, part 35 of 52."}}, {"slug": "hsk5-36", "position": 86, "title": {"fr": "HSK 5 · 36", "en": "HSK 5 · 36"}, "description": {"fr": "Vocabulaire du HSK 5, partie 36 sur 52.", "en": "HSK 5 vocabulary, part 36 of 52."}}, {"slug": "hsk5-37", "position": 87, "title": {"fr": "HSK 5 · 37", "en": "HSK 5 · 37"}, "description": {"fr": "Vocabulaire du HSK 5, partie 37 sur 52.", "en": "HSK 5 vocabulary, part 37 of 52."}}, {"slug": "hsk5-38", "position": 88, "title": {"fr": "HSK 5 · 38", "en": "HSK 5 · 38"}, "description": {"fr": "Vocabulaire du HSK 5, partie 38 sur 52.", "en": "HSK 5 vocabulary, part 38 of 52."}}, {"slug": "hsk5-39", "position": 89, "title": {"fr": "HSK 5 · 39", "en": "HSK 5 · 39"}, "description": {"fr": "Vocabulaire du HSK 5, partie 39 sur 52.", "en": "HSK 5 vocabulary, part 39 of 52."}}, {"slug": "hsk5-40", "position": 90, "title": {"fr": "HSK 5 · 40", "en": "HSK 5 · 40"}, "description": {"fr": "Vocabulaire du HSK 5, partie 40 sur 52.", "en": "HSK 5 vocabulary, part 40 of 52."}}, {"slug": "hsk5-41", "position": 91, "title": {"fr": "HSK 5 · 41", "en": "HSK 5 · 41"}, "description": {"fr": "Vocabulaire du HSK 5, partie 41 sur 52.", "en": "HSK 5 vocabulary, part 41 of 52."}}, {"slug": "hsk5-42", "position": 92, "title": {"fr": "HSK 5 · 42", "en": "HSK 5 · 42"}, "description": {"fr": "Vocabulaire du HSK 5, partie 42 sur 52.", "en": "HSK 5 vocabulary, part 42 of 52."}}]$zh$)
       AS n(slug text, position smallint, title jsonb, description jsonb)
ON CONFLICT (language_code, slug) DO UPDATE
   SET framework = excluded.framework, position = excluded.position,
       title = excluded.title, description = excluded.description;
DELETE FROM langues.words w USING langues.levels l
 WHERE w.level_id = l.id AND l.language_code = 'zh'
   AND l.slug IN ('hsk5-33', 'hsk5-34', 'hsk5-35', 'hsk5-36', 'hsk5-37', 'hsk5-38', 'hsk5-39', 'hsk5-40', 'hsk5-41', 'hsk5-42');
