SELECT 'zh', n.slug, 'HSK', n.position, n.title, n.description
  FROM jsonb_to_recordset($zh$[{"slug": "hsk6-1", "position": 103, "title": {"fr": "HSK 6 · 1", "en": "HSK 6 · 1"}, "description": {"fr": "Vocabulaire du HSK 6, partie 1 sur 100.", "en": "HSK 6 vocabulary, part 1 of 100."}}, {"slug": "hsk6-2", "position": 104, "title": {"fr": "HSK 6 · 2", "en": "HSK 6 · 2"}, "description": {"fr": "Vocabulaire du HSK 6, partie 2 sur 100.", "en": "HSK 6 vocabulary, part 2 of 100."}}, {"slug": "hsk6-3", "position": 105, "title": {"fr": "HSK 6 · 3", "en": "HSK 6 · 3"}, "description": {"fr": "Vocabulaire du HSK 6, partie 3 sur 100.", "en": "HSK 6 vocabulary, part 3 of 100."}}, {"slug": "hsk6-4", "position": 106, "title": {"fr": "HSK 6 · 4", "en": "HSK 6 · 4"}, "description": {"fr": "Vocabulaire du HSK 6, partie 4 sur 100.", "en": "HSK 6 vocabulary, part 4 of 100."}}, {"slug": "hsk6-5", "position": 107, "title": {"fr": "HSK 6 · 5", "en": "HSK 6 · 5"}, "description": {"fr": "Vocabulaire du HSK 6, partie 5 sur 100.", "en": "HSK 6 vocabulary, part 5 of 100."}}, {"slug": "hsk6-6", "position": 108, "title": {"fr": "HSK 6 · 6", "en": "HSK 6 · 6"}, "description": {"fr": "Vocabulaire du HSK 6, partie 6 sur 100.", "en": "HSK 6 vocabulary, part 6 of 100."}}, {"slug": "hsk6-7", "position": 109, "title": {"fr": "HSK 6 · 7", "en": "HSK 6 · 7"}, "description": {"fr": "Vocabulaire du HSK 6, partie 7 sur 100.", "en": "HSK 6 vocabulary, part 7 of 100."}}, {"slug": "hsk6-8", "position": 110, "title": {"fr": "HSK 6 · 8", "en": "HSK 6 · 8"}, "description": {"fr": "Vocabulaire du HSK 6, partie 8 sur 100.", "en": "HSK 6 vocabulary, part 8 of 100."}}, {"slug": "hsk6-9", "position": 111, "title": {"fr": "HSK 6 · 9", "en": "HSK 6 · 9"}, "description": {"fr": "Vocabulaire du HSK 6, partie 9 sur 100.", "en": "HSK 6 vocabulary, part 9 of 100."}}, {"slug": "hsk6-10", "position": 112, "title": {"fr": "HSK 6 · 10", "en": "HSK 6 · 10"}, "description": {"fr": "Vocabulaire du HSK 6, partie 10 sur 100.", "en": "HSK 6 vocabulary, part 10 of 100."}}]$zh$)
