  FROM jsonb_to_recordset($zh$[{"slug": "hsk6-21", "position": 123, "title": {"fr": "HSK 6 · 21", "en": "HSK 6 · 21"}, "description": {"fr": "Vocabulaire du HSK 6, partie 21 sur 100.", "en": "HSK 6 vocabulary, part 21 of 100."}}, {"slug": "hsk6-22", "position": 124, "title": {"fr": "HSK 6 · 22", "en": "HSK 6 · 22"}, "description": {"fr": "Vocabulaire du HSK 6, partie 22 sur 100.", "en": "HSK 6 vocabulary, part 22 of 100."}}, {"slug": "hsk6-23", "position": 125, "title": {"fr": "HSK 6 · 23", "en": "HSK 6 · 23"}, "description": {"fr": "Vocabulaire du HSK 6, partie 23 sur 100.", "en": "HSK 6 vocabulary, part 23 of 100."}}, {"slug": "hsk6-24", "position": 126, "title": {"fr": "HSK 6 · 24", "en": "HSK 6 · 24"}, "description": {"fr": "Vocabulaire du HSK 6, partie 24 sur 100.", "en": "HSK 6 vocabulary, part 24 of 100."}}, {"slug": "hsk6-25", "position": 127, "title": {"fr": "HSK 6 · 25", "en": "HSK 6 · 25"}, "description": {"fr": "Vocabulaire du HSK 6, partie 25 sur 100.", "en": "HSK 6 vocabulary, part 25 of 100."}}, {"slug": "hsk6-26", "position": 128, "title": {"fr": "HSK 6 · 26", "en": "HSK 6 · 26"}, "description": {"fr": "Vocabulaire du HSK 6, partie 26 sur 100.", "en": "HSK 6 vocabulary, part 26 of 100."}}, {"slug": "hsk6-27", "position": 129, "title": {"fr": "HSK 6 · 27", "en": "HSK 6 · 27"}, "description": {"fr": "Vocabulaire du HSK 6, partie 27 sur 100.", "en": "HSK 6 vocabulary, part 27 of 100."}}, {"slug": "hsk6-28", "position": 130, "title": {"fr": "HSK 6 · 28", "en": "HSK 6 · 28"}, "description": {"fr": "Vocabulaire du HSK 6, partie 28 sur 100.", "en": "HSK 6 vocabulary, part 28 of 100."}}, {"slug": "hsk6-29", "position": 131, "title": {"fr": "HSK 6 · 29", "en": "HSK 6 · 29"}, "description": {"fr": "Vocabulaire du HSK 6, partie 29 sur 100.", "en": "HSK 6 vocabulary, part 29 of 100."}}, {"slug": "hsk6-30", "position": 132, "title": {"fr": "HSK 6 · 30", "en": "HSK 6 · 30"}, "description": {"fr": "Vocabulaire du HSK 6, partie 30 sur 100.", "en": "HSK 6 vocabulary, part 30 of 100."}}]$zh$)
       AS n(slug text, position smallint, title jsonb, description jsonb)
ON CONFLICT (language_code, slug) DO UPDATE
   SET framework = excluded.framework, position = excluded.position,
       title = excluded.title, description = excluded.description;
DELETE FROM langues.words w USING langues.levels l
 WHERE w.level_id = l.id AND l.language_code = 'zh'
   AND l.slug IN ('hsk6-21', 'hsk6-22', 'hsk6-23', 'hsk6-24', 'hsk6-25', 'hsk6-26', 'hsk6-27', 'hsk6-28', 'hsk6-29', 'hsk6-30');
