  FROM jsonb_to_recordset($zh$[{"slug": "hsk6-61", "position": 163, "title": {"fr": "HSK 6 · 61", "en": "HSK 6 · 61"}, "description": {"fr": "Vocabulaire du HSK 6, partie 61 sur 100.", "en": "HSK 6 vocabulary, part 61 of 100."}}, {"slug": "hsk6-62", "position": 164, "title": {"fr": "HSK 6 · 62", "en": "HSK 6 · 62"}, "description": {"fr": "Vocabulaire du HSK 6, partie 62 sur 100.", "en": "HSK 6 vocabulary, part 62 of 100."}}, {"slug": "hsk6-63", "position": 165, "title": {"fr": "HSK 6 · 63", "en": "HSK 6 · 63"}, "description": {"fr": "Vocabulaire du HSK 6, partie 63 sur 100.", "en": "HSK 6 vocabulary, part 63 of 100."}}, {"slug": "hsk6-64", "position": 166, "title": {"fr": "HSK 6 · 64", "en": "HSK 6 · 64"}, "description": {"fr": "Vocabulaire du HSK 6, partie 64 sur 100.", "en": "HSK 6 vocabulary, part 64 of 100."}}, {"slug": "hsk6-65", "position": 167, "title": {"fr": "HSK 6 · 65", "en": "HSK 6 · 65"}, "description": {"fr": "Vocabulaire du HSK 6, partie 65 sur 100.", "en": "HSK 6 vocabulary, part 65 of 100."}}, {"slug": "hsk6-66", "position": 168, "title": {"fr": "HSK 6 · 66", "en": "HSK 6 · 66"}, "description": {"fr": "Vocabulaire du HSK 6, partie 66 sur 100.", "en": "HSK 6 vocabulary, part 66 of 100."}}, {"slug": "hsk6-67", "position": 169, "title": {"fr": "HSK 6 · 67", "en": "HSK 6 · 67"}, "description": {"fr": "Vocabulaire du HSK 6, partie 67 sur 100.", "en": "HSK 6 vocabulary, part 67 of 100."}}, {"slug": "hsk6-68", "position": 170, "title": {"fr": "HSK 6 · 68", "en": "HSK 6 · 68"}, "description": {"fr": "Vocabulaire du HSK 6, partie 68 sur 100.", "en": "HSK 6 vocabulary, part 68 of 100."}}, {"slug": "hsk6-69", "position": 171, "title": {"fr": "HSK 6 · 69", "en": "HSK 6 · 69"}, "description": {"fr": "Vocabulaire du HSK 6, partie 69 sur 100.", "en": "HSK 6 vocabulary, part 69 of 100."}}, {"slug": "hsk6-70", "position": 172, "title": {"fr": "HSK 6 · 70", "en": "HSK 6 · 70"}, "description": {"fr": "Vocabulaire du HSK 6, partie 70 sur 100.", "en": "HSK 6 vocabulary, part 70 of 100."}}]$zh$)
       AS n(slug text, position smallint, title jsonb, description jsonb)
ON CONFLICT (language_code, slug) DO UPDATE
   SET framework = excluded.framework, position = excluded.position,
       title = excluded.title, description = excluded.description;
DELETE FROM langues.words w USING langues.levels l
 WHERE w.level_id = l.id AND l.language_code = 'zh'
   AND l.slug IN ('hsk6-61', 'hsk6-62', 'hsk6-63', 'hsk6-64', 'hsk6-65', 'hsk6-66', 'hsk6-67', 'hsk6-68', 'hsk6-69', 'hsk6-70');
